module memory_address_decoder (
    input  wire [15:0] addr,
    input  wire        mem_en,
    output reg         cs_ram,
    output reg         cs_rom,
    output reg         cs_io
);

    always @(*) begin
        cs_ram = 1'b0;
        cs_rom = 1'b0;
        cs_io  = 1'b0;
        if (mem_en) begin
            case (addr[15:14])
                2'b00, 2'b01: cs_ram = 1'b1; // 0x0000 - 0x7FFF: 32KB SRAM
                2'b10:        cs_rom = 1'b1; // 0x8000 - 0xBFFF: 16KB ROM
                2'b11:        cs_io  = 1'b1; // 0xC000 - 0xFFFF: 16KB I/O
            endcase
        end
    end

endmodule
